===== EnsureUniqueTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;

/**
 * Rejects a create request whose telephone is already used by an existing owner. Runs
 * after {@link NormalizeOwnerTelephone} (so the request telephone is the E.164 value)
 * and before {@link BuildOwner}, so a collision is a 409 via
 * {@link DuplicateTelephoneException} before any owner is built or saved. Each stored
 * telephone is normalized to E.164 the same way before comparing.
 */
public class EnsureUniqueTelephone {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone()))) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}
===== EnsureUniqueEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;

/**
 * Rejects a create request whose email, lower-cased, is already used by an existing
 * owner. Email is optional, so a null or blank value is left through. Runs after
 * {@link NormalizeOwnerEmail} (so the request email is the canonical lower-cased value)
 * and before {@link BuildOwner}, so a collision is a 409 via
 * {@link DuplicateEmailException} before any owner is built or saved. Each stored email
 * is lower-cased the same way before comparing.
 */
public class EnsureUniqueEmail {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            String existingEmail = existing.getEmail();
            if (existingEmail != null && email.equals(EmailNormalizer.normalize(existingEmail))) {
                throw new DuplicateEmailException(email);
            }
        }
    }
}
===== EnsureUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create request whose last name and address already belong to an existing
 * owner, comparing both case-insensitively with collapsed whitespace. Runs before
 * {@link BuildOwner}, so a collision is a 409 via {@link DuplicateHouseholdException}
 * before any owner is built or saved. A request that opts in with
 * {@code sharesHousehold=true} is allowed through; {@link AssignHousehold} then groups it
 * with the existing owners under a shared household id.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        if (!Households.membersAt(ownerRepository, request.getLastName(), request.getAddress()).isEmpty()) {
            throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
        }
    }
}
===== TelephoneNormalizer =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Shared telephone normalization for the owner pipelines: convert a raw telephone to
 * E.164 form. Spaces, dashes and brackets are stripped; a number that already carries
 * a leading {@code '+'} keeps its country code, otherwise Australian country code
 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
 * national digits. The result is a {@code '+'} followed by 8 to 15 digits.
 *
 * <p>The national-number length must also match the country code: {@code '+61'}
 * (Australia) requires 9 national digits and {@code '+1'} (NANP) requires 10. A number
 * whose national part is the wrong length for its country is not valid E.164 here.
 *
 * <p>Used by {@link NormalizeOwnerTelephone} (which rejects a number that cannot form
 * valid E.164) and by {@link EnsureUniqueTelephone} (which normalizes each stored
 * telephone before comparing), so the two steps agree on what "normalized" means.
 */
final class TelephoneNormalizer {

    /** Country code -> the exact number of national digits E.164 requires for it. */
    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);

    private TelephoneNormalizer() {
    }

    /**
     * @return the E.164 representation of {@code telephone}, or {@code null} when it
     *         cannot form a valid E.164 number.
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        String cleaned = telephone.replaceAll("[\\s()-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        }
        else {
            if (cleaned.startsWith("0")) {
                cleaned = cleaned.substring(1);
            }
            digits = "61" + cleaned;
        }
        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
            return null;
        }
        return "+" + digits;
    }

    /**
     * @return whether the national digits following a recognised country code have the
     *         length that code requires. Unrecognised country codes are left to the
     *         general 8-to-15-digit E.164 shape check.
     */
    private static boolean hasValidNationalLength(String digits) {
        String code = countryCode(digits);
        if (code == null) {
            return true;
        }
        return digits.length() - code.length() == NATIONAL_LENGTHS.get(code);
    }

    /** The longest recognised country code that {@code digits} begins with, or null. */
    private static String countryCode(String digits) {
        String match = null;
        for (String code : NATIONAL_LENGTHS.keySet()) {
            if (digits.startsWith(code) && (match == null || code.length() > match.length())) {
                match = code;
            }
        }
        return match;
    }
}
===== EmailNormalizer =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Shared email handling for the owner pipelines: decide whether an address is
 * syntactically valid and normalize it to a canonical lower-cased form. Used by
 * {@link NormalizeOwnerEmail} so create and update agree on what a stored email
 * looks like.
 */
final class EmailNormalizer {

    /**
     * A single, unquoted local part, an {@code @}, then a dotted domain with a
     * multi-character final label. Deliberately conservative: it rejects an address
     * with no {@code @} or no domain while accepting ordinary mailbox addresses.
     */
    private static final Pattern EMAIL = Pattern.compile(
            "^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");

    private EmailNormalizer() {
    }

    static boolean isValid(String email) {
        return email != null && EMAIL.matcher(email.trim()).matches();
    }

    static String normalize(String email) {
        return email.trim().toLowerCase(Locale.ROOT);
    }
}
===== NormalizeOwnerTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the create-owner telephone to E.164 form (see {@link TelephoneNormalizer}).
 * Runs after {@link ValidateOwnerFields} (so the field is known to be present) and
 * before {@link BuildOwner}, mutating the published {@link OwnerFieldsDto} in place so
 * the owner is built and stored with the E.164 value. A number that cannot form valid
 * E.164 is rejected as a 400 via {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String e164 = TelephoneNormalizer.toE164(request.getTelephone());
        if (e164 == null) {
            throw new InvalidTelephoneException(request.getTelephone());
        }
        request.setTelephone(e164);
    }
}
